package br.com.onda;
import org.junit.Test;
import static org.junit.Assert.*;
import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import android.media.*;
import java.io.*;
@androidx.media3.common.util.UnstableApi
public class OriginalMediaTest {
 File fixture(String name)throws Exception{File file=File.createTempFile("original-fixture-",".bin",getInstrumentation().getTargetContext().getCacheDir());try(InputStream in=getInstrumentation().getContext().getAssets().open(name);OutputStream out=new FileOutputStream(file)){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return file;}
 @Test public void originalMp4AndM4aKeepExactBytes()throws Exception{for(String[] data:new String[][]{{"combined.mp4","mp4"},{"audio.m4a","m4a"}}){File source=fixture(data[0]),out=File.createTempFile("original-",".out",source.getParentFile());try{OriginalMedia.copy(source,out,data[1],()->{});assertArrayEquals(java.nio.file.Files.readAllBytes(source.toPath()),java.nio.file.Files.readAllBytes(out.toPath()));}finally{source.delete();out.delete();}}}
 @Test public void originalMp3IsNotConvertedAgain()throws Exception{File source=fixture("audio.m4a"),mp3=File.createTempFile("original-",".mp3",source.getParentFile()),out=File.createTempFile("original-",".out",source.getParentFile());try{Mp3Converter.convert(source,mp3,192,()->{});OriginalMedia.copy(mp3,out,"mp3",()->{});assertArrayEquals(java.nio.file.Files.readAllBytes(mp3.toPath()),java.nio.file.Files.readAllBytes(out.toPath()));}finally{source.delete();mp3.delete();out.delete();}}
 @Test public void htmlWrongContainerAndCancellationAreRejected()throws Exception{File source=fixture("combined.mp4"),out=File.createTempFile("original-",".out",source.getParentFile()),html=File.createTempFile("original-",".mp4",source.getParentFile());try{java.nio.file.Files.write(html.toPath(),"<html>Login required</html>".getBytes());for(File file:new File[]{html,source})try{OriginalMedia.copy(file,out,"m4a",()->{});fail();}catch(IOException expected){}try{OriginalMedia.copy(source,out,"mp4",()->{throw new InterruptedIOException();});fail();}catch(InterruptedIOException expected){}}finally{source.delete();out.delete();html.delete();}}
 @Test public void fullVideoAudioConvertsToRealMp3()throws Exception{File source=fixture("combined.mp4"),out=File.createTempFile("video-audio-",".mp3",source.getParentFile());try{Mp3Converter.convert(source,out,192,()->{});MediaExtractor e=new MediaExtractor();try{e.setDataSource(out.getPath());assertEquals(1,e.getTrackCount());assertEquals("audio/mpeg",e.getTrackFormat(0).getString(MediaFormat.KEY_MIME));assertTrue(e.getTrackFormat(0).getLong(MediaFormat.KEY_DURATION)>2000000);}finally{e.release();}}finally{source.delete();out.delete();}}
 @Test public void foregroundServiceSavesOriginalHttpsMp4()throws Exception{android.content.Context c=getInstrumentation().getTargetContext();File out=File.createTempFile("original-service-",".mp4",c.getCacheDir());c.getSharedPreferences("downloads",0).edit().clear().commit();android.content.Intent job=new android.content.Intent(c,MediaDownloadService.class).putExtra("first","https://raw.githubusercontent.com/cristianoarakaki-cpu/Arakaki/245b693e64cf5b5b33bc2a5f491a607f6a435655/Onda/tests/fixtures/download.mp4").putExtra("original",true).putExtra("format","mp4").putExtra("destination",android.net.Uri.fromFile(out).toString()).putExtra("title","Direct original");try{getInstrumentation().runOnMainSync(()->c.startForegroundService(job));long end=System.currentTimeMillis()+90000;String status="";while(System.currentTimeMillis()<end){status=c.getSharedPreferences("downloads",0).getString("status","");if(!MediaDownloadService.activeDownload&&status.startsWith("Download concluído"))break;if(!MediaDownloadService.activeDownload&&status.startsWith("Operação interrompida"))fail(status);Thread.sleep(200);}assertTrue(status,status.startsWith("Download concluído"));MediaExtractor e=new MediaExtractor();try{e.setDataSource(out.getPath());assertEquals(2,e.getTrackCount());}finally{e.release();}}finally{c.stopService(job);out.delete();}}
}
